#include "what_changed/collectors.hpp"
#include "what_changed/diff.hpp"
#include "what_changed/output.hpp"
#include "what_changed/util.hpp"
#include <algorithm>
#include <iostream>
#include <set>

namespace {constexpr int usage=2,invalid_snapshot=3,io_error=4,collection_error=5;
void help(){std::cout<<"what-changed 1.0.0 - observe Linux system changes\n\nUsage:\n  what-changed capture -o FILE [--category NAME] [--exclude NAME] [--track PATH] [--include-transient]\n  what-changed compare BEFORE AFTER [--format text|json|markdown] [--include-transient]\n  what-changed show FILE [--format text|json|markdown]\n  what-changed validate FILE\n  what-changed categories\n  what-changed --version\n\nSnapshots contain observations, not causal diagnoses.\n";}
wc::Snapshot load(const std::string&p){return wc::parse_snapshot(wc::read_file_bounded(p,16U*1024U*1024U));}
bool known(const std::string&s){const auto&v=wc::supported_categories();return std::find(v.begin(),v.end(),s)!=v.end();}}
int main(int argc,char**argv){try{if(argc<2){help();return usage;}std::string cmd=argv[1];if(cmd=="--help"||cmd=="-h"||cmd=="help"){help();return 0;}if(cmd=="--version"||cmd=="version"){std::cout<<"what-changed "<<WHAT_CHANGED_VERSION<<"\n";return 0;}if(cmd=="categories"){for(const auto&s:wc::supported_categories())std::cout<<s<<"\n";return 0;}if(cmd=="capture"||cmd=="create"){wc::CaptureOptions o;std::string output;for(int i=2;i<argc;++i){std::string a=argv[i];auto need=[&](){if(++i>=argc)throw std::invalid_argument("missing value for "+a);return std::string(argv[i]);};if(a=="-o"||a=="--output")output=need();else if(a=="--category"){auto x=need();if(!known(x))throw std::invalid_argument("unknown category: "+x);o.include.insert(x);}else if(a=="--exclude"){auto x=need();if(!known(x))throw std::invalid_argument("unknown category: "+x);o.exclude.insert(x);}else if(a=="--track")o.config_paths.emplace_back(need());else if(a=="--include-transient")o.include_transient=true;else throw std::invalid_argument("unknown option: "+a);}if(output.empty())throw std::invalid_argument("capture requires -o FILE");auto s=wc::capture(o);wc::atomic_write_private(output,wc::serialize_snapshot(s));std::cerr<<"Created snapshot "<<output<<" with mode 0600\n";return 0;}if(cmd=="compare"){if(argc<4)throw std::invalid_argument("compare requires BEFORE and AFTER");std::string before=argv[2],after=argv[3];wc::Format f=wc::Format::Text;bool transient=false;for(int i=4;i<argc;++i){std::string a=argv[i];if(a=="--format"&&++i<argc)f=wc::parse_format(argv[i]);else if(a=="--include-transient")transient=true;else throw std::invalid_argument("unknown compare option: "+a);}std::cout<<wc::format_diff(wc::compare(load(before),load(after),transient),f);return 0;}if(cmd=="show"){if(argc<3)throw std::invalid_argument("show requires FILE");wc::Format f=wc::Format::Text;for(int i=3;i<argc;++i){std::string a=argv[i];if(a=="--format"&&++i<argc)f=wc::parse_format(argv[i]);else throw std::invalid_argument("unknown show option: "+a);}std::cout<<wc::format_metadata(load(argv[2]),f);return 0;}if(cmd=="validate"){if(argc!=3)throw std::invalid_argument("validate requires FILE");load(argv[2]);std::cout<<argv[2]<<": valid schema version 1 snapshot\n";return 0;}throw std::invalid_argument("unknown command: "+cmd);}catch(const wc::JsonError&e){std::cerr<<"what-changed: invalid snapshot: "<<e.what()<<"\n";return invalid_snapshot;}catch(const std::invalid_argument&e){std::cerr<<"what-changed: "<<e.what()<<"\nTry 'what-changed --help'.\n";return usage;}catch(const std::filesystem::filesystem_error&e){std::cerr<<"what-changed: filesystem error: "<<e.what()<<"\n";return io_error;}catch(const std::exception&e){std::cerr<<"what-changed: "<<e.what()<<"\n";return collection_error;}}
